select case when p.stock_qty >= 412 then 'high' when p.stock_qty >= 114 then 'mid' else 'low' end as stock_qty_bucket, max(ss.revenue) - min(ss.revenue) as revenue_range from store_sales ss inner join products p on ss.product_id = p.id inner join stores s on s.id = ss.store_id where p.cost is not null group by case when p.stock_qty >= 412 then 'high' when p.stock_qty >= 114 then 'mid' else 'low' end having max(ss.revenue) - min(ss.revenue) >= 27 order by stock_qty_bucket
